if(location.protocol==='file:')for(const a of document.querySelectorAll('a[href$="AuMaNET-design-handover.zip"]'))a.hidden=true;const filter=document.querySelector('#screen-filter');const cards=[...document.querySelectorAll('.library .screen-card')];filter.addEventListener('input',()=>{let visible=0;for(const card of cards){const match=card.textContent.toLowerCase().includes(filter.value.toLowerCase().trim());card.hidden=!match;if(match)visible++;}document.querySelector('#screen-count').textContent=visible+' screen'+(visible===1?'':'s');document.querySelector('#empty-filter').hidden=visible!==0;});
